head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > maxlength]<br/>SearchBox 컴포넌트에 입력 가능한 최대 길이를 설정합니다.",
    "validation" : [
        "validate() 메소드 실행 시 입력값이 maxlength 설정값보다 크면 유효성 체크는 실패로 처리됩니다.",
        "validate() 실패 시 displaymessage='true' 이면 시스템 기본 메시지 'n자를 초과하여 입력할 수 없습니다.' 가 출력됩니다.",
        "validate() 실패 메시지는 invalidMessage 속성으로 변경할 수 있습니다.",
        "validate() 실패 메시지는 invalidMessageFunc 속성으로 변경할 수 있습니다.",
        "minlength 또는 minByteLength 속성을 maxlength 값보다 크게 설정한 경우 유효성 체크는 항상 실패로 처리됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};


scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}


scwin.fn_msg = function() {
    var type = this.getType();
    switch (type) {
        case "maxLength" : return "사용자 정의 maxLength 메시지 입니다.";
        default : return "Not valid.";
    }
}


// target1 : maxlength=5, 입력값='가나다라마바' → 시스템 기본 메시지
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("가나다라마바");
};

scwin.btn_validate1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validate(target1);
}

// target2 : maxlength=5, invalidMessage 설정
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("가나다라마바");
};

scwin.btn_validate2_onclick = function (e) {
    scwin.btn_setValue2_onclick();
    scwin.check_validate(target2);
}

// target3 : maxlength=5, invalidMessageFunc 설정
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("가나다라마바");
};

scwin.btn_validate3_onclick = function (e) {
    scwin.btn_setValue3_onclick();
    scwin.check_validate(target3);
}

// target4 : maxlength=5, minlength=8 (모순 조건 → 항상 실패)
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("abcde");
};

scwin.btn_validate4_onclick = function (e) {
    scwin.btn_setValue4_onclick();
    scwin.check_validate(target4);
};

// target5 : maxlength=5, minByteLength=8 (모순 조건 → 항상 실패)
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("abcde");
};

scwin.btn_validate5_onclick = function (e) {
    scwin.btn_setValue5_onclick();
    scwin.check_validate(target5);
};
